// CSD_RATIONALE_BEGIN
// Root cause: The previous strategy called CloseSpanIfComplete on every
// constrained step. After generating a bare variable name like "n", the
// parser accepts it as a complete arithmetic expression and immediately closes
// the span, yielding <<n>> instead of <<n * (mult + 1)>>. This produced 0%
// accuracy because every span contained only a single-token expression.
//
// Fix: Replace the CloseSpanIfComplete inner loop entirely with a single call
// to CloseSpanWithinBudget. This helper generates forward inside the span,
// tracks the LONGEST complete prefix found across its entire step budget,
// and emits ">>" only at that longest point. If the model generates
// n (complete), then n * (incomplete), then n * (mult + 1) (complete again),
// CloseSpanWithinBudget closes at the full formula, not at the bare variable.
//
// Strategy:
//   Phase 1: Unconstrained generation (up to 85% of budget) using
//            UnconstrainedStep + RenderedEndsWith to detect "<<".
//   Phase 2: When inside a span, call CloseSpanWithinBudget with all
//            remaining budget to find the longest complete expression.
//   Phase 3: If no span was ever completed, force-open "<<" with
//            OpenConstrainedSpan, then CloseSpanWithinBudget with whatever
//            budget remains.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)):
//   Phase 1 loop – EOS branch: we break without modifying span state; invariant
//     carries over unchanged.
//   Phase 1 loop – append-no-<< branch: insideConstrainedOut stays false,
//     making the implication vacuously true.
//   Phase 1 loop – append-with-<< branch: EnterObservedConstrainedSpan sets
//     currentConstrainedOut := []; parser.IsValidPrefix([]) holds by method
//     precondition. insideConstrainedOut := true.
//   Phase 2 (CloseSpanWithinBudget): library postcondition explicitly guarantees
//     !insideOut ==> currentOut == [] and insideOut ==> parser.IsValidPrefix(currentOut).
//   Phase 3 OpenConstrainedSpan: sets currentConstrainedOut := [] (valid by
//     method precondition parser.IsValidPrefix([])).
//   Phase 3 CloseSpanWithinBudget: same library postcondition as Phase 2.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1 loop: each iteration increments steps by 1 (UnconstrainedStep costs
//     +1 including EOS). EOS path appends 0 tokens; non-EOS path appends exactly
//     1 token. EnterObservedConstrainedSpan costs +0 and leaves generated
//     unchanged. Net per iteration: +1 step, at most +1 visible token. ✓
//   Phase 2 (CloseSpanWithinBudget with budget b): postcondition guarantees
//     |generatedOut| <= |generated_before| + b. We add exactly b to steps,
//     so |generated| <= |generatedPrefix| + steps_before + b = |generatedPrefix|
//     + steps_after. ✓
//   Phase 3 OpenConstrainedSpan: appends exactly 1 token ("<<"), steps += 1.
//     Balanced: |generated| grows by 1, steps grows by 1. ✓
//   Phase 3 CloseSpanWithinBudget: identical argument to Phase 2. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. At the very end write: The answer is <<EXPR>> where EXPR is a complete arithmetic expression using the problem variable names and operators (+, -, *, /, parentheses). EXPR must contain at least one operator — do not write just a single variable name. Example: The answer is <<(n * price) - discount>>.");

var steps: nat := 0;
var hasCompletedSpan: bool := false;

// Allow up to 85% of budget for free reasoning; reserve ~15% for the span.
var freeBudget: nat := (maxSteps * 85) / 100;
if freeBudget > maxSteps { freeBudget := maxSteps; }

// ── Phase 1: Free generation watching for naturally emitted "<<" ─────────────
while steps < freeBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  invariant freeBudget <= maxSteps
  decreases freeBudget - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg;
    insideConstrainedOut := ei;
    currentConstrainedOut := ec;
  }
}

// ── Phase 2: Close the naturally-opened span using longest-complete tracking ──
if insideConstrainedOut && steps < maxSteps {
  var spanBudget: nat := maxSteps - steps;
  var wg, wi, wc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget);
  generated := wg;
  insideConstrainedOut := wi;
  currentConstrainedOut := wc;
  steps := steps + spanBudget;
  if !insideConstrainedOut {
    hasCompletedSpan := true;
  }
}

// ── Phase 3: Force a span if none has completed ───────────────────────────────
if !insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg;
  insideConstrainedOut := fi;
  currentConstrainedOut := fc;
  steps := steps + 1;

  if steps < maxSteps {
    var spanBudget2: nat := maxSteps - steps;
    var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget2);
    generated := wg2;
    insideConstrainedOut := wi2;
    currentConstrainedOut := wc2;
    steps := steps + spanBudget2;
  }
}

cost := steps;

